import * as fs from 'node:fs';
import * as path from 'node:path';
import type { ProcDef } from '../defineProc.js';
import { auditTableDDL } from '../ddl.js';
import { procDDL } from './ddl.js';
import { bundleProc, type ProcBuildInput, type AuditBundleConfig, type CatalogBundleConfig } from './bundle.js';

export interface BuildSprocsOpts {
  /**
   * Procs to build. Each entry has the proc ref (for DDL) and an absolute
   * path to its TS source file (for the bundler).
   */
  procs: ProcBuildInput[];
  /** Output file path. Parent dirs are created if missing. */
  out: string;
  /** Audit table config — must match what the local target uses at runtime. */
  audit: AuditBundleConfig;
  /**
   * Install-target db/schema. Passed to the bundler so `defineCatalog(...)`
   * values get inlined as fully-qualified strings at compile time.
   */
  catalog: CatalogBundleConfig;
  /** Default `{ hybrid: true }`. */
  schema?: { hybrid?: boolean };
}

/**
 * Build a flat `install.sql` containing the audit-table DDL plus one
 * `CREATE OR REPLACE PROCEDURE` per proc. Operator deploys via
 * `snow sql -c <conn> -f <out>`.
 */
export async function buildSprocs(opts: BuildSprocsOpts): Promise<void> {
  const parts: string[] = [
    '-- Generated by @snowflake/synapse/build. Do not edit.',
    '',
    auditTableDDL({
      table: opts.audit.table,
      ...(opts.audit.appIdField ? { appIdColumn: opts.audit.appIdField } : {}),
      hybrid: opts.schema?.hybrid ?? true,
    }),
    '',
  ];

  for (const input of opts.procs) {
    const body = await bundleProc(input, opts.audit, opts.catalog);
    parts.push(procDDL(input.proc, {
      body,
      ...(input.proc.executeAs ? { executeAs: input.proc.executeAs } : {}),
    }));
    parts.push('');
  }

  await fs.promises.mkdir(path.dirname(opts.out), { recursive: true });
  await fs.promises.writeFile(opts.out, parts.join('\n'), 'utf8');
}
